"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[630],{4815:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Creates a `feces` library instance that watches the supplied `world` for component changes\\nand exposes `apply`, `delta`, `full`, `reserve`, and other helpers.\\n```lua\\n-- may be used like this in a module of its own\\nlocal world = jecs.world()\\nlocal feces = lib.new(jecs, world)\\n```","params":[{"name":"jecs","desc":"The `jecs` module instance (require(\\"@rbx/jecs\\")).","lua_type":"Jecs"},{"name":"world","desc":"The `jecs.World` instance to observe and mutate.","lua_type":"World"},{"name":"group?","desc":"Optional initial group to use for the returned instance (creates default group).","lua_type":"Group"},{"name":"debugPrints?","desc":"Enable debug printing.","lua_type":"boolean"}],"returns":[{"desc":"Returns a new `feces` instance.","lua_type":"feces"}],"function_type":"static","source":{"line":29,"path":"src/api.luau"}},{"name":"combine","desc":"`combine` translates [`Changes`](#Changes) objects into per-player [`Applyable`](api/feces#Applyable) packets,\\nready to be serialized or sent to each client as one object with all the necessary updates.\\nSee the [simple setup here](/docs/setup#simple).","params":[{"name":"changes","desc":"The changes object returned from `delta`.","lua_type":"Changes"},{"name":"deleted","desc":"Optional deletes object returned from `delta`.","lua_type":"Deletes?"}],"returns":[{"desc":"Per-player packets prepared from the changes+deletes.","lua_type":"{ [Player]: Applyable }"}],"function_type":"static","source":{"line":40,"path":"src/api.luau"}},{"name":"reserve","desc":"Reserves a lookup namespace of `size` entries and returns a `Group`. The returned `Group` can be\\npassed to `lookup`, `ref`, `delta`, `apply`, etc., to isolate replication to that namespace.\\nUse [`feces:setGroup`](/api/feces#setGroup) to add a particular entity to a replication group.\\n\\nThe primary goal of these is to allow serializing entites of specific types with a set amount of bits.\\nSo for example, you could have a maximum of 8 racecars at a time in your racing game, and you could create\\na replication group with a size of 8, and then serialize those entities\' lookup ids as 3 *whole* ___bits___.\\n\\n**Or** if you\'re feeling fancy you can reserve a group then create an instance of feces from it:\\n```lua\\nlocal group = lib.reserve(24)\\nlib.new(jecs, myWorld, group)\\n```","params":[{"name":"size","desc":"number of lookup slots to reserve","lua_type":"number"},{"name":"debugLocation","desc":"whether to use debug.info for debugging","lua_type":"boolean?"}],"returns":[{"desc":"A `Group` object with its own lookup space.","lua_type":"Group"}],"function_type":"static","source":{"line":61,"path":"src/api.luau"}}],"properties":[],"types":[{"name":"Group","desc":"An object representing a reserved or default lookup namespace. The `feces` instance itself behaves as a `Group`\\nwhen used as the default/global group.","fields":[{"name":"origin","lua_type":"string","desc":"Human-readable origin for warnings and debugging (e.g. \\"script:23 reserve()\\")"},{"name":"size","lua_type":"number","desc":"Maximum count of entities for this group"},{"name":"lookups","lua_type":"{ [LocalEntity]: LookupEntity }","desc":"Mapping local entity -> lookup id"},{"name":"refs","lua_type":"{ [LookupEntity]: LocalEntity }","desc":"Mapping lookup id -> local entity"}],"source":{"line":72,"path":"src/api.luau"}},{"name":"Applyable","desc":"Represents a per-player packet that can be applied locally.\\nUse [`feces:apply`](#apply) to enact the changes in `Applyable` into the [`feces.world`](#world).","lua_type":"{ [Component]: { [LookupEntity]: { value: any, action?: number,}}, __d = { LookupEntity }}","source":{"line":79,"path":"src/api.luau"}},{"name":"Changes","desc":"Produced by [`feces:delta`](#delta) and accepted by [`feces.combine`](#combine).","lua_type":"{ [Component]: { [Player]: { value: { [LookupEntity]: any }, remove: { LookupEntity }, none: { LookupEntity }, } } }","source":{"line":85,"path":"src/api.luau"}},{"name":"Deletes","desc":"Produced by [`feces:delta`](#delta)","lua_type":"{ [Player]: { LookupEntity } }","source":{"line":91,"path":"src/api.luau"}},{"name":"LocalEntity","desc":"An entity in the world at [`feces.world`](#world)","lua_type":"number","source":{"line":97,"path":"src/api.luau"}},{"name":"LookupEntity","desc":"An lookup id for an entity that *may* exist in [`feces.world`](#world).","lua_type":"number","source":{"line":103,"path":"src/api.luau"}}],"name":"lib","desc":"The feces library only provides 3 functions\\n- [`new`](#new) -- creates new feces class\\n- [`combine`](#combine) -- combines `Changes` and `Deletes` objects into one [`Applyable`](api/feces#Applyable) per player\\n- [`reserve`](#reserve) -- creates a `Group` structure that can be used by any feces object\\n\\nAlso, [`combine`](#combine) and [`reserve`](#reserve) can both be used from an instance of [`feces`](/api/feces)\\nvia `feces.combine` and `feces.reserve` respectively (using . operator instead of :)","source":{"line":11,"path":"src/api.luau"}}')}}]);